            for c in range(len(result[0])):
                if result[r][c] != output_demo[r][c]:
                    mismatches.append((r, c, result[r][c], output_demo[r][c]))
    print(f"  {name}: {'MATCH' if match else 'MISMATCH'}")
    if not match:
        print(f"    {len(mismatches)} mismatches at positions: {mismatches[:5]}...")
    return match

